class Solution:
    def findDuplicate(self, nums: List[int]) -> int:
        n = len(nums)
        l, r = 1, n - 1
        ans = -1
        while l <= r:
            mid = (l + r) >> 1
            cnt = 0
            for i in range(n):
                if nums[i] <= mid:
                    cnt += 1
            if cnt <= mid:
                l = mid + 1
            else:
                r = mid - 1
                ans = mid
        return ans

class Solution:
    def findDuplicate(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0
        bitMax = 31
        while (n - 1) >> bitMax == 0:
            bitMax -= 1
        for bit in range(bitMax + 1):
            x = y = 0
            for i in range(n):
                if nums[i] & (1 << bit) > 0:
                    x += 1
                if i >= 1 and i & (1 << bit) > 0:
                    y += 1
            if x > y:
                ans |= 1 << bit
        return ans

class Solution:
    def findDuplicate(self, nums: List[int]) -> int:
        slow, fast = 0, 0
        slow = nums[slow]
        fast = nums[nums[fast]]
        while slow != fast:
            slow = nums[slow]
            fast = nums[nums[fast]]
        slow = 0
        while slow != fast:
            slow = nums[slow]
            fast = nums[fast]
        return slow
